from review import card,save,DATE
i='TCS-3806';_,c=card(i);refs=c['references']
refs[0]['locator']='Section 2.1 Algorithm 1 and Theorem 4; Section 5 first open question. Insertion-only edge streams, fixed order across passes, 2^k passes and O(k log n) bits.'
refs += [dict(id='full',title='Towards a Theory of Parameterized Streaming Algorithms',authors='Rajesh Chitnis; Graham Cormode',year=2019,url='https://arxiv.org/abs/1911.09650',pdf_url='https://arxiv.org/pdf/1911.09650v1',locator='Full version submitted 20 November 2019; Figure 2 distinguishes deterministic upper bounds and randomized lower bounds; Section 2.1 and concluding first open question.'),dict(id='kernel',title='Parameterized Complexity of Streaming Diameter and Connectivity Problems',authors='Jelle J. Oostveen; Erik Jan van Leeuwen',year=2024,url='https://doi.org/10.1007/s00453-024-01246-z',pdf_url='https://arxiv.org/pdf/2207.04872v2',locator='Algorithmica 86, 2885–2928, published 19 June 2024; full revision 18 July 2024. Introduction explicitly retains the question; Theorem 45 outputs a 2k-vertex kernel using O(k³) passes in edge arrival and O(k log n) bits. Lemma 44 concerns an auxiliary bipartite graph.')]
notes=['Restored the simultaneous polynomial-in-k pass bound and O(k log n)-bit space bound, including uniform constants and fixed edge order across passes.','Defined simple graphs, the supplied budget k, exact output, all-stream success and worst-case resource accounting.','Uses the bounded-error randomized convention of the full source’s lower-bound scope; its known 2^k-pass upper bound is deterministic.','Read the 2024 streamed-kernel result and its explicit remaining-question paragraph; distinguished emitting a kernel from solving it in the same memory.','Removed suggested branching or kernelization approaches from the problem statement.']
save(i,dict(
 title='Polynomial-pass streaming Vertex Cover',
 formal='Is there a single streaming algorithm and absolute constants C,D,c>0 such that, for every n≥2, every integer budget 1≤k≤n and every insertion-only edge stream of a simple undirected graph G on vertex set [n], the algorithm uses at most Ck log₂(2n) bits of working memory and at most D(k+1)^c passes, and outputs either a vertex cover of size at most k or NO if no such cover exists? Randomization is allowed, with probability at least 2/3 of a correct output for every fixed input stream. The memory and pass bounds must hold for every input and every outcome of the random bits. Each pass reads the same stream in the same fixed but arbitrary order; the polynomial exponent and constants are independent of n and k.',
 definitions='The input supplies n and k in binary and then the edges {u,v}, 1≤u<v≤n, each exactly once, in an arbitrary order. There are no edge deletions, random-order promise or adjacency queries. Vertex labels use ⌈log₂(n+1)⌉ bits; isolated vertices are included in [n] even if they never occur in the stream. A vertex cover is a subset X⊆[n] such that every edge has at least one endpoint in X. The algorithm must output some such X with |X|≤k when one exists and NO otherwise; neither a minimum-cardinality cover nor a 2-approximation is the target. The value k is a supplied upper budget, not a promise that G has a small cover. A pass is one left-to-right scan of the read-only edge sequence. The stream may be restarted at its beginning between passes but may not be rewritten, reordered, or accessed at arbitrary positions. A partial last scan counts as a pass. The algorithm retains only its bounded working memory across passes. Memory includes stored vertex names, counters, intermediate structures, retained random bits, and any proposed cover that is subsequently read; an output device is write only and cannot serve as additional scratch memory. Randomness consists of fresh independent fair bits; correctness probability is over these bits for each fixed stream, whose order is independent of them. Two-sided error is allowed, meaning that either a false NO or an invalid cover is a failure. The uniform algorithm must halt on every input and every random-bit outcome; total computation time and time per edge have no additional bound, but all workspace is charged. Neither nonuniform advice depending on n,k nor free unbounded-precision storage is allowed. Deterministic algorithms are included as a special case. A constant success probability strictly above 1/2 can be amplified without changing the requested asymptotic memory and pass forms; 2/3 fixes the convention. This card allows bounded-error randomization, consistent with the lower-bound scope of the full source; the existing upper bound it seeks to improve happens to be deterministic. The k=0 case is omitted only because a single scan determines whether the graph is edgeless. There is no restriction k=O(log n). Polynomially many passes means a fixed power of k, independent of n, not a polynomial in n or an arbitrary function of k.',
 question_type='yes_no',
 answer_criterion='Give an algorithm with the stated uniform correctness, memory and worst-case pass guarantees, or prove that no bounded-error algorithm can meet them for all n,k and all edge orders. A negative result restricted to deterministic algorithms does not refute the randomized formulation. An algorithm using O(k² log n) space, exponentially many passes, a stronger stream model, or a pre-supplied cover does not meet the target. Producing a small kernel as a separate output stream is insufficient unless the full task is also solved within the same bounds.',
 context_blocks=[dict(title='Known upper bounds trade space for passes',text='The source gives a deterministic exact algorithm using 2^k passes and O(k log n) bits. One-pass algorithms instead use roughly quadratic dependence on k in their memory. The open question asks whether the linear dependence in memory can coexist with only polynomial dependence in the number of passes.',citation='primary'),dict(title='Unrestricted computation does not remove the storage restriction',text='The streaming model constrains retained information and access to input rather than computation time. A full graph or a large reduced instance cannot be placed in uncharged memory while an offline solver runs.',citation='kernel'),dict(title='A later kernel can be emitted using the desired memory',text='The 2024 paper outputs a reduced Vertex Cover instance on at most 2k vertices using O(k³) passes in the edge-arrival model and O(k log n) bits of memory. The reduced graph may still have O(k²) edges. Its introduction explicitly says the polynomial-pass, O(k log n)-space solving question remains open.',citation='kernel'),dict(title='A bipartite subroutine is not a solver for all graphs',text='The later paper’s small-space minimum-cover lemma concerns an auxiliary bipartite graph and is used in obtaining the reduced instance. It does not compute an exact minimum cover of the original arbitrary graph with the requested resources.',citation='kernel')],
 why='Asks whether repeated access can replace the extra factor of k in the memory needed for exact parameterized graph computation, while retaining only polynomially many scans. This is a basic space-versus-access tradeoff for an NP-hard graph problem.',
 progress=[dict(date='2019',text='The source establishes the deterministic 2^k-pass, O(k log n)-bit algorithm and asks for polynomially many passes at the same memory scale.',citation='primary'),dict(date='2024-06-19',text='A 2k-vertex kernel can be emitted as a stream using polynomially many passes and O(k log n) bits; the paper expressly distinguishes this from solving Vertex Cover within those resources.',citation='kernel')],
 references=refs,status='open',status_note='Read the full source’s algorithm and question, and the 2024 journal introduction, stream-model definitions, Theorem 45 and auxiliary bipartite-cover lemma. The 2024 paper explicitly retains the solving problem. Searches through 12 September 2026 also found a 2025 Utrecht thesis reiterating the question, but that thesis was checked only through its indexed concluding passage and publication record. No general solution was found; searches are not exhaustive.',model_self_contained=True,requires_context=False,
 review_note='Expands the source question into a bounded-error randomized streaming formulation and states that convention explicitly. The 2/3 success level has no asymptotic significance. The graph is presented by edge arrival, not grouped adjacency lists, and the space bound applies throughout any computation on a kernel.',
 importance=dict(score=c['importance']['score'],method='editorial',reason='A clean exact graph problem testing whether polynomially many input scans suffice at memory proportional to the parameter, with direct relevance to the structure of parameterized streaming complexity. Existing score retained.',assessed_on=DATE),
 working_summary=dict(sentences=['The graph arrives as an arbitrary fixed-order stream of edges, and k is a proposed upper bound on a vertex cover’s size.','The target is an exact cover or a correct NO answer using O(k log n) bits and polynomially many passes.','Known algorithms attain that memory bound with 2^k passes, while one-pass solutions use more memory.','Randomized algorithms with constant success probability are allowed, but space and pass bounds are worst case.','A 2024 polynomial-pass kernelization uses the desired memory to emit a small graph; it does not solve that graph within the same resources.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full','kernel'])
),notes=notes,checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2207.04872','https://research-portal.uu.nl/en/publications/a-diametral-path-through-streams-and-forbidden-patterns/'])
